func build_deck() -> Array:
    var deck: Array = []
    for suit in range(4):
        for rank in range(2, 15):
            deck.append(CardData.make(suit, rank))
    deck.append(CardData.make(0, 15))
    deck.append(CardData.make(1, 15))
    deck.shuffle()
    return deck

